package net.civeira.phylax.feature.observe.observedalert.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.valueobject.LinkVO;

@RequiredArgsConstructor
public class LinkValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<LinkVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getLink() {
    return value.flatMap(LinkVO::getLink);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<LinkVO> getLinkValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param link
   * @return
   */
  public T link(LinkVO link) {
    this.value = Optional.of(link);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param link
   * @return
   */
  public T link(Optional<LinkVO> link) {
    this.value = link;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param link
   * @return
   */
  public T link(String link) {
    this.value = Optional.of(LinkVO.from(link));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T linkNull() {
    this.value = Optional.of(LinkVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public LinkVO readLink(final Optional<ObservedAlert> original, final ConstraintFailList fails) {
    return value.orElse(original.map(ObservedAlert::getLinkValue).orElseGet(LinkVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetLink() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetLinkIfMatches(final String field) {
    if ("link".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
